 add(o){const e={id:this.nextId++,hp:100,maxHp:o.hp||100,dead:false,cd:[0,0,0,0],mana:120,maxMana:120,buffs:{},status:{},shield:0,attackCd:0,kills:0,deaths:0,assists:0,level:1,xp:0,gold:0,streak:0,age:0,angle:0,...o};this.entities.push(e);return e;}
 spawnHero(idx,team,slot){const h=HEROES[idx];return this.add({kind:'hero',hero:idx,team,slot,lane:[1,0,2,0,2][slot],x:team?146:14,z:44+slot*3,hp:h.hp,r:.85,range:h.range,damage:h.damage,rate:h.rate,speed:h.speed*.78});}
 emit(type,data={}){this.events.push({type,time:this.time,...data});if(this.events.length>150)this.events.shift();}
 buff(e,id){return (e.buffs?.[id]||0)>this.time;}
